"""RESULTS.md and web/public/data/dashboard.json from reports/*.json. Deterministic; do not edit the outputs."""

from __future__ import annotations

import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
REPORTS = ROOT / "reports"


def load(name: str) -> dict:
    return json.loads((REPORTS / f"{name}.json").read_text())


def tests() -> dict:
    out = subprocess.run(
        [sys.executable, "-m", "pytest", "--collect-only", "-q"], cwd=ROOT, capture_output=True, text=True
    ).stdout
    m = re.search(r"(\d+) tests? collected", out)
    web = sum(len(re.findall(r"^\s*it\(", p.read_text(), re.M)) for p in (ROOT / "web" / "test").glob("*.test.tsx"))
    return {"python": int(m.group(1)) if m else 0, "web": web}


def pct(x: float) -> str:
    return f"{x * 100:.1f}%"


def main() -> None:
    dev, held, cl = load("claims_dev"), load("claims_heldout"), load("claims")
    rep, gd, pl = load("replenishment"), load("gdpr"), load("pipeline")
    data = {
        "tests": tests(),
        "claims": {
            "register": cl["register"],
            "dev": {
                k: dev[k]
                for k in ("items", "accuracy", "accuracy_ci95", "false_passes", "not_allowed", "false_flags", "allowed")
            },
            "heldout": {
                k: held[k]
                for k in (
                    "items",
                    "accuracy",
                    "accuracy_ci95",
                    "false_passes",
                    "not_allowed",
                    "false_pass_rate_ci95",
                    "false_flags",
                    "allowed",
                    "false_flag_rate_ci95",
                )
            },
            "heldout_misses": [{"product": e["product"], "text": e["text"]} for e in held["errors"]],
            "catalogue": {k: v for k, v in cl["catalogue"].items() if k != "rows"},
            "catalogue_rows": cl["catalogue"]["rows"],
            "search": cl["search"],
            "guard": cl["guard"],
            "examples": cl["examples"],
        },
        "replenishment": {
            k: rep[k]
            for k in ("world", "release", "months", "served_mae_days", "served_rule_mae_days", "versions", "events")
        },
        "gdpr": gd,
        "pipeline": {k: pl[k] for k in ("vertex_spec", "bigquery_sql", "prefect_run", "lineage")},
    }
    web = ROOT / "web" / "public" / "data"
    web.mkdir(parents=True, exist_ok=True)
    (web / "dashboard.json").write_text(json.dumps(data, indent=1, sort_keys=True, ensure_ascii=False) + "\n")
    (ROOT / "RESULTS.md").write_text(render(data))
    print("RESULTS.md, web/public/data/dashboard.json")


def render(d: dict) -> str:
    c, r, g = d["claims"], d["replenishment"], d["gdpr"]
    dev, held, s = c["dev"], c["heldout"], c["search"]["methods"]
    rel = r["release"]
    L = [
        "# Results",
        "",
        f"Generated by `scripts/report.py` from `reports/*.json`. Tests: {d['tests']['python']} Python, {d['tests']['web']} web.",
        "",
        "## Claim checker",
        "",
        f"Register: {c['register']['claims']} authorised claims for {c['register']['nutrients']} nutrients, "
        "from the annex of Regulation (EU) No 432/2012.",
        "",
        "| | Dev (built against) | Held-out (written first, run once) |",
        "|---|---:|---:|",
        f"| Sentences | {dev['items']} | {held['items']} |",
        f"| Accuracy | {pct(dev['accuracy'])} | {pct(held['accuracy'])} (95% CI {pct(held['accuracy_ci95'][0])} to {pct(held['accuracy_ci95'][1])}) |",
        f"| Not-allowed text let through (false passes) | {dev['false_passes']} of {dev['not_allowed']} | "
        f"{held['false_passes']} of {held['not_allowed']} |",
        f"| Allowed text flagged (false flags) | {dev['false_flags']} of {dev['allowed']} | {held['false_flags']} of {held['allowed']} |",
        "",
        "Held-out false passes, as they came out:",
        "",
        *[f'- {m["product"]}: "{m["text"]}"' for m in c["heldout_misses"]],
        "",
        f"Catalogue audit: {c['catalogue']['with_findings']} of {c['catalogue']['products']} product descriptions have a "
        f"finding; {c['catalogue']['blocked']} contain text that must be removed.",
        "",
        "## Search and advice",
        "",
        f"{c['search']['queries']} customer questions, top {c['search']['k']}. A result is relevant when the product's "
        "composition makes it eligible for an authorised claim on the asked-for need.",
        "",
        "| Index | Recall | Precision | Results with nothing lawful to say for the need |",
        "|---|---:|---:|---:|",
        *[
            f"| {m} | {pct(v['recall_at_k'])} | {pct(v['precision_at_k'])} | {pct(v['results_without_a_lawful_claim_for_the_need'])} |"
            for m, v in s.items()
        ],
        "",
        "Guard against a drafter that embellishes claims:",
        "",
        "| Embellish rate | Made-up sentences | Reached a customer | Rewritten | Blocked |",
        "|---:|---:|---:|---:|---:|",
        *[
            f"| {x['embellish_rate']:.0%} | {x['made_up_sentences']} | {x['reached_customer']} | {x['rewritten']} | {x['blocked']} |"
            for x in c["guard"]
        ],
        "",
        "## Run-out model and its operation",
        "",
        f"{r['world']['customers']:,} simulated customers, {r['world']['orders']:,} orders, {r['world']['months']} months; "
        f"trained on the first {r['world']['train_months']}.",
        "",
        f"- At release, on the last month's matured labels: MAE {rel['v1_holdout']['mae_days']:.1f} days vs "
        f"{rel['rule_holdout']['mae_days']:.1f} for the pack-size rule; reminders too late "
        f"{pct(rel['v1_holdout']['reminders_too_late'])} vs {pct(rel['rule_holdout']['reminders_too_late'])}.",
        f"- Over the {len(r['months'])}-month replay: MAE {r['served_mae_days']:.1f} days for what was served vs "
        f"{r['served_rule_mae_days']:.1f} for the rule.",
        "",
        "| Month | Orders | Labels matured | Live MAE | Rule MAE | Drift alerts | Champion | Actions |",
        "|---:|---:|---:|---:|---:|---|---:|---|",
        *[
            f"| {m['month']} | {m['orders']} | {m['live'].get('n', 0)} | {m['live'].get('mae_days', 0):.1f} | "
            f"{m['live'].get('rule_mae_days', 0):.1f} | {', '.join(m['psi_alerts']) or ''} | v{m['champion']} | "
            f"{'; '.join(m['actions'])} |"
            for m in r["months"]
        ],
        "",
        "## GDPR erasure",
        "",
        f"{g['erased_customers']} customers erased from identities, orders, features and the personalisation index; "
        f"model versions trained on them were marked for retraining by day {g['retrain_due_day']}, retrained, and "
        f"the old versions purged ({', '.join('v' + str(v) for v in g['purged_versions'])}). Audit after retraining: "
        + (
            "nothing left in any store."
            if all(not any(v for k, v in a.items()) for a in g["after_retrain"])
            else "items remain (see reports/gdpr.json)."
        ),
        "",
    ]
    return "\n".join(L)


if __name__ == "__main__":
    main()
